mgc_code:
def get_dir(path, dest, saltenv='base', template=None, gzip=None, **kwargs):
    """
    Used to recursively copy a directory from the salt master

    CLI Example:

    .. code-block:: bash

        salt '*' cp.get_dir salt://path/to/dir/ /minion/dest

    get_dir supports the same template and gzip arguments as get_file.
    """
    if template is None:
        template = __salt__['config.option']('file_client')
    if gzip is None:
        gzip = __salt__['config.option']('gzip_compress')
    if not os.path.isdir(dest):
        os.makedirs(dest)
    for root, dirs, files in os.walk(path):
        for f in files:
            src = os.path.join(root, f)
            dest = os.path.join(dest, os.path.relpath(src, path))
            if os.path.exists(dest):
                continue
            __salt__['cp.get_file'](src, dest, saltenv=saltenv, template=template, gzip=gzip, **kwargs)

