mgc_code:
def aprint(*values, sep=None, end='\n', flush=False, streams=None, use_stderr=False, loop=None):
    """Asynchronous equivalent to *print*."""
    if streams is None:
        streams = [sys.stdout]
    if use_stderr:
        streams.append(sys.stderr)
    if loop is None:
        loop = asyncio.get_event_loop()
    coros = [loop.create_task(stream.write(sep.join(str(v) for v in values) + end)) for stream in streams]
    return asyncio.gather(*coros)

