mgc_code:
def create(cls, community, record, user=None, expires_at=None,
               notify=True):
        """Create a record inclusion request to a community.

        :param community: Community object.
        :param record: Record API object.
        :param expires_at: Time after which the request expires and shouldn't
            be resolved anymore.
        """
        if not isinstance(community, Community):
            raise TypeError('community must be a Community object')
        if not isinstance(record, Record):
            raise TypeError('record must be a Record object')
        if not isinstance(user, User) and user is not None:
            raise TypeError('user must be a User object')
        if not isinstance(expires_at, datetime) and expires_at is not None:
            raise TypeError('expires_at must be a datetime object')

        if user is None:
            user = User.current()

        if expires_at is None:
            expires_at = datetime.utcnow() + timedelta(days=1)

        request = cls(community=community, record=record, user=user,
                      expires_at=expires_at)
        request.save()

        if notify:
            request.notify()

        return request

