def do_attach(self, arg):
        """
        attach <target> [target...] - attach to the given process(es)
        """
        if self.cmdprefix:
            raise CmdError("prefix not allowed")
        targets = self.input_process_list( self.split_tokens(arg, 1) )
        if not targets:
            print("Error: missing parameters")
        else:
            debug = self.debug
            for pid in targets:
                try:
                    debug.attach(pid)
                    print("Attached to process (%d)" % pid)
                except Exception:
                    print("Error: can't attach to process (%d)" % pid)

mgc_code:
def do_attach(self, arg):
        """
        attach <target> [target...] - attach to the given process(es)
        """
        if not arg:
            self.do_help('attach')
            return
        targets = arg.split()
        for target in targets:
            try:
                pid = int(target)
            except ValueError:
                self.do_help('attach')
                return
            try:
                self.attach(pid)
            except Exception as e:
                self.msg('attach failed: %s' % e)

