def _adjust_inserted_indices(inserted_indices_list, prune_indices_list):
        """Adjust inserted indices, if there are pruned elements."""
        if not prune_indices_list:
            return inserted_indices_list

        # Adjust inserted indices, if there are pruned elements.
        for i, inserted_indices in enumerate(inserted_indices_list):
            if not inserted_indices:
                continue
            for j, inserted_index in enumerate(inserted_indices):
                if inserted_index in prune_indices_list:
                    inserted_indices_list[i][j] = inserted_index - 1
        return inserted_indices_list

