def name_tree(tree):
    """
    Names all the tree nodes that are not named or have non-unique names, with unique names.

    :param tree: tree to be named
    :type tree: ete3.Tree

    :return: void, modifies the original tree
    """
    if tree.name is None:
        tree.name = 'tree'
    if len(tree.get_leaves()) == 0:
        tree.name = 'tree'
    else:
        tree.name = 'tree' + str(len(tree.get_leaves()))
    for node in tree.traverse():
        if node.name is None:
            node.name = 'node' + str(node.idx)
        if len(node.get_leaves()) == 0:
            node.name = 'node' + str(node.idx)
        else:
            node.name = 'node' + str(node.idx) + str(len(node.get_leaves()))

