            raise ValueError("You must specify a virtual server identifier.")
        if not name:
            raise ValueError("You must specify a name for the image.")
        if note:
            raise ValueError("You cannot specify a note when capturing a single disk.")
        cli_capture_disk(env, identifier, name)
